import{_ as a,o as t,c as r,a0 as n}from"./chunks/framework.BQGW-Zpy.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"project/faq.md","filePath":"project/faq.md"}'),o={name:"project/faq.md"};function s(i,e,d,l,p,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p><strong>Why blockchain, and not a shared database?</strong> The parties involved, a licensed PSP, a licensed payout partner, a regulator, are independently licensed and don&#39;t trust each other&#39;s internal databases. A database owned by any one of them is a record that party can revise. Hedera supplies ordering and a timestamp that none of them control.</p><p><strong>Aren&#39;t you an unlicensed payment institution?</strong> No, we never hold funds or crypto-assets at any point. See <a href="./../legal/why-this-is-legal.html">Why This Is Legal</a>.</p><p><strong>Why Hedera specifically?</strong> Fixed, USD-denominated fees; deterministic (not probabilistic) finality in ~3 seconds; and Hedera Consensus Service is purpose-built for an ordered, timestamped, append-only event stream, exactly the primitive a compliance trail needs. See <a href="./../architecture/trust-layer.html">The Trust Layer</a>.</p><p><strong>Do you always settle on Hedera?</strong> No, see <a href="./../architecture/settlement-layer.html">The Settlement Layer</a>. Hedera is preferred but not exclusive; large amounts or unsupported partner chains route elsewhere.</p><p><strong>Is this production-ready?</strong> No. It&#39;s a sandbox/testnet prototype demonstrating the architecture and the verification mechanism. See <a href="./roadmap.html">Roadmap</a> for what&#39;s deliberately not built yet.</p><p><strong>What data is exposed on-chain?</strong> Only a hash and a pseudonymous, HMAC&#39;d reference, never a name, an IBAN, an amount, or a document. See <a href="./../legal/compliance-data.html">Compliance Data &amp; Privacy</a>.</p>',7)])])}const u=a(o,[["render",s]]);export{m as __pageData,u as default};
